#include <iostream>
#include <vector>
#include <string>
using namespace std;

long long cover(int covered, int full, const vector<int>& masks) {
    if (covered == full) return 1;
    int low = ~covered & (covered + 1);
    long long total = 0;
    for (int mask : masks) {
        if ((mask & low) && !(mask & covered)) total += cover(covered | mask, full, masks);
    }
    return total;
}

int main() {
    long long m;
    long long k;
    cin >> m >> k;
    vector<string> sets(k);
    for (int i = 0; i < k; i++) {
        cin >> sets[i];
    }

    vector<int> masks;
    for (const string& row : sets) {
        int mask = 0;
        for (int i = 0; i < m; i++) {
            if (row[i] == '1') mask |= 1 << i;
        }
        masks.push_back(mask);
    }
    cout << cover(0, (1 << m) - 1, masks) << "\n";

    return 0;
}

